const item = items[0];
let raw = item.json.data || item.json;
if (item.binary && item.binary.data) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
}
const db = typeof raw === 'string' ? JSON.parse(raw) : raw;
const done = new Set(db.done || []);
let pick = null;
for (const service of db.services) {
  for (const area of db.areas) {
    for (const brand of db.brands) {
      const filename = `${service}-${area}.asp`;
      if (!done.has(filename)) {
        pick = { area, brand, service, filename, agentData: db };
        break;
      }
    }
    if (pick) break;
  }
  if (pick) break;
}
if (!pick) {
  return [{ json: { skip: true, message: 'All area/brand/service combinations are in done' } }];
}
const areaTitle = pick.area.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
const serviceTitle = pick.service.replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
pick.areaTitle = areaTitle;
pick.serviceTitle = serviceTitle;
pick.title = `${serviceTitle} ${areaTitle} - 24/7 Emergency | ColdDirect`;
return [{ json: pick }];

const prev = items[0].json;
const pick = $node['Pick Next Area'].json;
let html = '';
if (prev.content && prev.content[0] && prev.content[0].text) html = prev.content[0].text;
else if (prev.candidates && prev.candidates[0]) html = prev.candidates[0].content.parts[0].text;
html = String(html || '').replace(/^```[a-z]*\n?/i, '').replace(/```$/,'');
if (!html) throw new Error('Claude returned empty HTML');
return [{ json: { ...pick, html, filename: pick.filename } }];

const pick = $node['Pick Next Area'].json;
const created = items[0].json;
const db = JSON.parse(JSON.stringify(pick.agentData));
if (!Array.isArray(db.done)) db.done = [];
if (!db.done.includes(pick.filename)) db.done.push(pick.filename);
return [{ json: { filename: pick.filename, created: created.data || created, agentData: db, html: pick.html } }];
